/**
 * Runtime for `virtual:generated-layouts` (generated by `node/plugins/layouts.ts`).
 *
 * Ported from vite-plugin-vue-layouts-next@3.2.0 (MIT, https://github.com/loicduong/vite-plugin-vue-layouts-next)
 * with unchanged behavior: `meta.layout` (name, `false` or `{ name, props }`), `meta.layoutProps`,
 * the default/fallback layout, lazy-layout preloading, `setPageLayout` and `useLayout`.
 */
import type { Component, ComputedRef } from 'vue'
import type { RouteLocationNormalized, RouteLocationNormalizedLoaded, Router, RouteRecordNormalized, RouteRecordRaw } from 'vue-router'
import { computed, defineAsyncComponent, defineComponent, h, hasInjectionContext, inject, shallowRef } from 'vue'
import { matchedRouteKey, routerKey, RouterView, START_LOCATION, useRoute, useRouter } from 'vue-router'

export type LayoutName = string | false
export type LayoutProps = Record<string, unknown>

/** Object form of `meta.layout`. */
export interface LayoutOptions {
  /** Layout name, `false` for no layout, or omitted for the default layout. */
  name?: LayoutName
  props?: LayoutProps
}

export type LayoutMeta = LayoutName | LayoutOptions

const LAZY = Symbol.for('valaxy:layouts:lazy')

export type LazyLayout = (() => Promise<{ default: Component } | Component>) & { [LAZY]: true }
export type LayoutMap = Record<string, Component | LazyLayout>

interface ResolvedLayout {
  name: LayoutName
  props?: LayoutProps
}

type Meta = Record<string, any> | undefined

function readLayoutMeta(meta: Meta): { name: LayoutName | undefined, props?: LayoutProps } {
  const layout = meta?.layout
  if (layout !== null && typeof layout === 'object') {
    return {
      name: layout.name,
      props: layout.props ?? meta?.layoutProps,
    }
  }
  return {
    name: layout,
    props: meta?.layoutProps,
  }
}

function declaresLayout(meta: Meta) {
  const layout = meta?.layout
  if (layout !== null && typeof layout === 'object')
    return layout.name !== false
  return !!layout
}

/** Without `withLayout`, the returned getter hides the generated layout routes. */
export function createGetRoutes(router: Router, withLayout: true): RouteRecordNormalized[]
export function createGetRoutes(router: Router, withLayout?: false): () => RouteRecordNormalized[]
export function createGetRoutes(router: Router, withLayout = false) {
  const routes = router.getRoutes()
  if (withLayout)
    return routes
  return () => routes.filter(route => !route.meta.isLayout)
}

function hasChildWithLayout(route: RouteRecordRaw): boolean {
  if (!route.children || route.children.length === 0)
    return false
  return route.children.some((child) => {
    if (declaresLayout(child.meta))
      return true
    if (child.meta?.isLayout)
      return true
    return hasChildWithLayout(child)
  })
}

export interface SetupLayoutsOptions {
  inheritDefaultLayout: boolean
}

export function createSetupLayouts(wrapper: Component, options: SetupLayoutsOptions) {
  const { inheritDefaultLayout } = options

  function wrap(route: RouteRecordRaw, keepRootPath: boolean): RouteRecordRaw {
    return {
      path: route.path,
      component: wrapper,
      children: keepRootPath && route.path === '/' ? [route] : [{ ...route, path: '' } as RouteRecordRaw],
      meta: { isLayout: true },
    } as RouteRecordRaw
  }

  function deepSetupLayout(routes: RouteRecordRaw[], top = true): RouteRecordRaw[] {
    return routes.map((route) => {
      const childHasLayout = top && !inheritDefaultLayout && (route.children?.length ?? 0) > 0
        ? hasChildWithLayout(route)
        : false
      if (route.children && route.children.length > 0)
        route.children = deepSetupLayout(route.children, false)
      if (top) {
        if (!route.component && route.children?.find(r => (r.path === '' || r.path === '/') && r.meta?.isLayout))
          return route
        if (readLayoutMeta(route.meta).name !== false) {
          if (inheritDefaultLayout || !childHasLayout)
            return wrap(route, true)
        }
      }
      if (declaresLayout(route.meta))
        return wrap(route, false)
      return route
    })
  }

  return (routes: readonly RouteRecordRaw[]) => deepSetupLayout(routes as RouteRecordRaw[])
}

/**
 * The virtual module wraps its async imports with this, so a lazy entry is always
 * identified explicitly rather than guessed from its shape - unlike Vue Router's route
 * components, a bare functional component is a perfectly valid, non-lazy layout here.
 */
export function lazyLayout(loader: () => Promise<{ default: Component } | Component>): LazyLayout {
  return Object.assign(loader, { [LAZY]: true as const })
}

function isLazyLayout(entry: unknown): entry is LazyLayout {
  return typeof entry === 'function' && (entry as any)[LAZY] === true
}

const PREFIX = '[valaxy:layouts]'

/** In-place override set by `setPageLayout`; cleared on navigation to another path. */
const override = shallowRef<ResolvedLayout | null>(null)
const guardedRouters = new WeakSet<Router>()
/** `defaultLayout` of the last created wrapper; shared with `useLayout()`. */
let resolvedDefaultLayout = 'default'

/**
 * Change the layout of the current page without navigating, optionally passing props
 * to the layout component. The override lasts until the router navigates to a different `path`.
 */
export function setPageLayout(name: LayoutName | null | undefined, props?: LayoutProps) {
  override.value = name == null ? null : { name, props }
}

/**
 * Reactive name of the layout resolved for the current route.
 * `false` when no wrapper is rendered around it (a static `layout: false` route, or
 * one deliberately left unwrapped because `inheritDefaultLayout` is `false`).
 */
export function useLayout(): ComputedRef<LayoutName> {
  const route = useRoute()
  return computed(() => {
    const own = innermostLayoutRecord(route)
    if (!own)
      return false
    return resolveLayoutFor(route, own, override.value).name
  })
}

function innermostLayoutRecord(route: RouteLocationNormalizedLoaded) {
  const { matched } = route
  for (let i = matched.length - 1; i >= 0; i--) {
    if (matched[i].meta.isLayout)
      return matched[i]
  }
}

/**
 * Layout (name and props) the wrapper whose generated record is `own` renders for `route`.
 *
 * The static layout comes from the wrapped record's own meta (`||` fallback to the
 * default), so nested trees keep one layout per level. Dynamic inputs - the
 * `setPageLayout` override and a guard assignment to the merged `route.meta.layout` /
 * `route.meta.layoutProps` - apply only to the innermost wrapper. A dynamic layout
 * brings its own props and never inherits the page's static ones.
 */
function resolveLayoutFor(route: RouteLocationNormalized, own: RouteRecordNormalized, overrideValue: ResolvedLayout | null): ResolvedLayout {
  const { matched } = route
  const idx = matched.indexOf(own)
  const page = readLayoutMeta(matched[idx + 1]?.meta)
  const staticLayout: ResolvedLayout = {
    name: page.name || resolvedDefaultLayout,
    props: page.props,
  }
  if (matched.slice(idx + 2).some(r => r.meta.isLayout))
    return staticLayout
  if (overrideValue)
    return overrideValue

  const meta = route.meta as Record<string, any>
  const staticMerged = matched.reduce<unknown>((m, r) => (r.meta as Meta)?.layout ?? m, undefined)
  const staticMergedProps = matched.reduce<unknown>((m, r) => (r.meta as Meta)?.layoutProps ?? m, undefined)
  const guardProps = meta.layoutProps !== staticMergedProps ? meta.layoutProps : undefined
  if (meta.layout != null && meta.layout !== staticMerged) {
    const guard = readLayoutMeta({ layout: meta.layout, layoutProps: guardProps })
    return {
      name: guard.name ?? resolvedDefaultLayout,
      props: guard.props,
    }
  }
  return {
    name: staticLayout.name,
    props: guardProps ?? staticLayout.props,
  }
}

function unwrapModule(mod: any) {
  return mod && typeof mod === 'object' && 'default' in mod ? mod.default : mod
}

/** Options-API navigation guards that never run on a layout component (see `checkRouteGuards`). */
const ROUTE_GUARD_NAMES = ['beforeRouteEnter', 'beforeRouteUpdate', 'beforeRouteLeave'] as const

/** `fallbackLayout` is rendered when the requested layout is not in `layouts`; if it is missing too, the page renders without a layout. */
export function createLayoutWrapper(layouts: LayoutMap, defaultLayout: string, fallbackLayout = defaultLayout): Component {
  resolvedDefaultLayout = defaultLayout
  /** Lazy layouts already loaded (by the `beforeResolve` preload or an async render). */
  const resolved = new Map<string, Component>()
  /** In-flight loads, so a layout's factory runs at most once. */
  const pending = new Map<string, Promise<Component>>()
  /** `defineAsyncComponent` per name, for renders that happen before the preload. */
  const asyncCache = new Map<string, Component>()
  const warned = new Set<string>()
  let fallbackWarned = false
  const guardWarned = new Set<string>()

  /**
   * Layouts are rendered by `LayoutWrapper`, not matched as route components, so Vue
   * Router never calls their Options-API route guards; the Composition-API
   * `onBeforeRouteUpdate`/`onBeforeRouteLeave` still work since they subscribe directly
   * to the router. Skipped for a `defineAsyncComponent` wrapper that hasn't resolved
   * yet - the caller passes the real component once loaded.
   */
  function checkRouteGuards(name: string, comp: any) {
    if (guardWarned.has(name) || !comp || (typeof comp !== 'object' && typeof comp !== 'function'))
      return
    const target = 'default' in comp ? comp.default : comp
    if (!target)
      return
    const opts = target.__vccOpts ?? target
    const guards = ROUTE_GUARD_NAMES.filter(g => opts?.[g])
    if (guards.length > 0) {
      guardWarned.add(name)
      console.warn(`${PREFIX} Layout "${name}" declares ${guards.join(', ')}; layouts are not route components, so these guards will not run. Use onBeforeRouteUpdate/onBeforeRouteLeave or a router guard instead.`)
    }
  }

  function load(name: string, loader: LazyLayout) {
    let promise = pending.get(name)
    if (!promise) {
      promise = Promise.resolve(loader()).then((mod) => {
        const component = unwrapModule(mod)
        resolved.set(name, component)
        return component
      }, (error) => {
        pending.delete(name)
        throw error
      })
      pending.set(name, promise)
    }
    return promise
  }

  function resolveComponent(name: string): Component | undefined {
    const loaded = resolved.get(name)
    if (loaded) {
      checkRouteGuards(name, loaded)
      return loaded
    }
    const entry = layouts[name]
    if (!entry)
      return undefined
    if (isLazyLayout(entry)) {
      let created = asyncCache.get(name)
      if (!created) {
        created = defineAsyncComponent(() => load(name, entry))
        asyncCache.set(name, created)
      }
      return created
    }
    checkRouteGuards(name, entry)
    return entry
  }

  function resolveLayout(name: string) {
    const found = resolveComponent(name)
    if (found)
      return found
    if (!warned.has(name)) {
      warned.add(name)
      console.warn(`${PREFIX} Layout "${name}" not found, falling back to "${fallbackLayout}"`)
    }
    const fallback = resolveComponent(fallbackLayout)
    if (!fallback && !fallbackWarned) {
      fallbackWarned = true
      console.warn(`${PREFIX} Fallback layout "${fallbackLayout}" not found, rendering without a layout`)
    }
    return fallback
  }

  const preload = async (to: RouteLocationNormalized, from: RouteLocationNormalized) => {
    const keepOverride = from === START_LOCATION || to.path === from.path
    for (const rec of to.matched) {
      if (!rec.meta.isLayout)
        continue
      const { name } = resolveLayoutFor(to, rec, keepOverride ? override.value : null)
      if (name === false)
        continue
      const key = layouts[name] ? name : fallbackLayout
      const entry = layouts[key]
      if (isLazyLayout(entry) && !resolved.has(key))
        await load(key, entry)
    }
  }

  function installGuards(router: Router) {
    if (guardedRouters.has(router))
      return
    guardedRouters.add(router)
    router.beforeResolve(preload)
    router.afterEach((to, from, failure) => {
      if (failure)
        return
      if (from !== START_LOCATION && to.path !== from.path)
        override.value = null
    })
  }

  return defineComponent({
    name: 'LayoutWrapper',
    beforeRouteEnter(to, from) {
      if (hasInjectionContext()) {
        const router = inject(routerKey, null)
        if (router)
          installGuards(router)
      }
      return preload(to, from)
    },
    setup() {
      const route = useRoute()
      const own = inject(matchedRouteKey)!
      installGuards(useRouter())
      const layout = computed(() => resolveLayoutFor(route, own.value!, override.value))
      return () => {
        const { name, props } = layout.value
        if (name === false)
          return h(RouterView)
        const LayoutComponent = resolveLayout(name)
        return LayoutComponent
          ? h(LayoutComponent, props ? { ...props } : null, { default: () => h(RouterView) })
          : h(RouterView)
      }
    },
  })
}
